with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'グランド・オダリスク', 'ジャン＝オーギュスト＝ドミニク・アングル', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/La_grande_odalisque_-_Jean-Auguste_Dominique_Ingres_-_Mus%C3%A9e_du_Louvre_Peintures_RF_1158.jpg/960px-La_grande_odalisque_-_Jean-Auguste_Dominique_Ingres_-_Mus%C3%A9e_du_Louvre_Peintures_RF_1158.jpg', '1814年、ナポリ王妃カロリーヌ・ミュラの注文で描かれた裸婦像で、ルーヴル美術館が所蔵します。ハーレムの女性を振り返る姿で描き、異国趣味を古典的な美しさで包みました。背中や腕は実際の人体より長く引き伸ばされ、1819年のサロンでは不自然だと批判されましたが、線の流れを優先したこの誇張こそが見どころ。冷たいほど滑らかな肌と、孔雀の羽の扇や布の質感の描き分けにも注目です。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:La_grande_odalisque_-_Jean-Auguste_Dominique_Ingres_-_Musée_du_Louvre_Peintures_RF_1158.jpg'),
    (2, '鷹見泉石像', '渡辺崋山', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/A_portrait_of_Takami_Senseki_by_Watanabe_Kazan.jpg/960px-A_portrait_of_Takami_Senseki_by_Watanabe_Kazan.jpg', '1837年（天保8年）、渡辺崋山が古河藩の家老で蘭学者でもあった鷹見泉石を描いた肖像画で、国宝として東京国立博物館が所蔵します。崋山は西洋の画法を学び、顔に陰影をつけて立体感を出しながら、衣は伝統的な線描でまとめました。正装で座る泉石の、穏やかで知的なまなざしが印象的です。蘭学を通じて交流した二人の関係もうかがえる、江戸後期の肖像画の傑作です。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:A_portrait_of_Takami_Senseki_by_Watanabe_Kazan.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
