insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('大阪府20世紀美術コレクションと子供の作品展', '中之島のアートエリアB1で「つくってみようよ展覧会 アートと出会う瞬間 ペティルはピースフレイバー」が開かれている。', '「つくってみようよ展覧会 アートと出会う瞬間 ペティルはピースフレイバー」が、2026年11月20日から12月23日まで大阪・中之島のアートエリアB1で開かれている。キュレーターは檜山真有。大阪府20世紀美術コレクションから、アンリ・カルティエ＝ブレッソン、アルフレッド・スティーグリッツ、植田正治、入江泰吉らの写真や、イマンツ・ティラースの《アラブル・ロード》（2000）、田中一光のポスターなどを紹介する。府内3校の子供たちや夏のワークショップ参加者の制作物もあわせて並ぶ。入場無料。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33349',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('突撃する近衛猟騎兵士官', 'The Charging Chasseur', 'テオドール・ジェリコー', 'Théodore Géricault',
        1812,
        (select slug from public.art_movements where slug = 'romanticism'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/An_Officer_of_the_Imperial_Horse_Guards_Charging_-_G%C3%A9ricault_%28Louvre_INV_4885%29.jpg/960px-An_Officer_of_the_Imperial_Horse_Guards_Charging_-_G%C3%A9ricault_%28Louvre_INV_4885%29.jpg', '21歳のジェリコーが1812年のサロンに出品し、金賞を得たデビュー作です。ナポレオン軍の騎兵士官が、後ろ足で立ち上がる馬の上で振り返る瞬間を、大きな画面に斜めの構図で描きました。煙にかすむ戦場と荒々しい筆づかい、ルーベンスを思わせる豊かな色彩が、緊張と躍動を伝えます。理想化された静かな英雄像を重んじた新古典主義に対し、動きと感情を前に出したこの作品は、ロマン主義の幕開けを告げる一枚となり、のちの《メデューズ号の筏》へとつながっていきます。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:An_Officer_of_the_Imperial_Horse_Guards_Charging_-_Géricault_(Louvre_INV_4885).jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('麦わら帽子の自画像', 'Self Portrait in a Straw Hat', 'エリザベート・ヴィジェ＝ルブラン', 'Élisabeth Vigée Le Brun',
        1782,
        (select slug from public.art_movements where slug = 'rococo'),
        'ロンドン・ナショナル・ギャラリー', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Self-portrait_in_a_Straw_Hat_by_Elisabeth-Louise_Vig%C3%A9e-Lebrun.jpg/960px-Self-portrait_in_a_Straw_Hat_by_Elisabeth-Louise_Vig%C3%A9e-Lebrun.jpg', 'マリー・アントワネットの肖像画家として知られるヴィジェ＝ルブランが、1782年にフランドルでルーベンスの《麦わら帽子》を見て、それに倣って描いた自画像です。花を飾った帽子をかぶり、パレットを手に屋外の光の中に立つ姿は、明るく親しみやすい印象を与えます。帽子の影が顔に落ちても肌が明るく見えるよう、光の反射を細やかに描き分けた点が見どころです。ロココの華やかさを受け継ぎつつ、気取らない自然な表情を描いたことで、肖像画に新しい親しさをもたらしました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Self-portrait_in_a_Straw_Hat_by_Elisabeth-Louise_Vigée-Lebrun.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('死神のいる自画像', 'Self-Portrait with Death Playing the Fiddle', 'アルノルト・ベックリン', 'Arnold Böcklin',
        1872,
        (select slug from public.art_movements where slug = 'symbolism'),
        'ベルリン旧国立美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Arnold_Boecklin-fiedelnder_Tod.jpg/960px-Arnold_Boecklin-fiedelnder_Tod.jpg', '1872年、ミュンヘンでベックリンが描いた自画像で、ベルリン旧国立美術館が所蔵します。筆とパレットを手にした画家が耳を澄ませるように振り向き、その背後では骸骨の死神が弦の一本だけ残ったヴァイオリンを弾いています。死を身近に置いて生のはかなさを思う「メメント・モリ」の伝統を、画家自身の創作の場面に重ねたのが特徴です。目に見えない霊感や死の気配を描こうとする姿勢は、のちの《死の島》とともに、象徴主義の画家たちに大きな影響を与えました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Arnold_Boecklin-fiedelnder_Tod.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

