values ('商人ゲオルク・ギーゼの肖像', 'The Merchant Georg Gisze', 'ハンス・ホルバイン（子）', 'Hans Holbein the Younger',
        1532,
        (select slug from public.art_movements where slug = 'renaissance'),
        'ベルリン絵画館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Hans_Holbein_der_J%C3%BCngere_-_Der_Kaufmann_Georg_Gisze_-_Google_Art_Project.jpg/960px-Hans_Holbein_der_J%C3%BCngere_-_Der_Kaufmann_Georg_Gisze_-_Google_Art_Project.jpg', '1532年、ロンドンに移ったホルバインが、ハンザ同盟の商館で働くダンツィヒ出身の商人ゲオルク・ギーゼを描いた肖像画です。手紙を開く人物のまわりには、ガラスの花瓶に挿したカーネーション、秤、時計、印章や書類が細密に描かれ、商人としての仕事と暮らしぶりを伝えます。ガラスの透明感や布の質感など、北方ルネサンスの写実の伝統を受け継ぎつつ、人物の内面を静かに映す表情に力点を置いた点が見どころ。のちのイギリス宮廷肖像画の手本となりました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Hans_Holbein_der_Jüngere_-_Der_Kaufmann_Georg_Gisze_-_Google_Art_Project.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ピエール・ピュヴィス・ド・シャヴァンヌ', 'Pierre Puvis de Chavannes', 'シャヴァンヌ',
        1824, 1898, 'west', array['symbolism']::text[],
        '静かで平面的な画面の壁画で知られる、フランス象徴主義の画家。', '1824年、フランスのリヨンに生まれました。はじめは父と同じく技師を志しましたが、病気で学業を中断し、療養のために訪れたイタリアで画家を志します。帰国後はドラクロワやトマ・クチュールに学びました。

1850年にサロンにデビューしたものの、その後は落選が続きます。一方で、パリ大改造で建てられた公共建築の壁画を多く任されるようになりました。イタリアで見たフレスコ画にならい、中間色を使い、陰影や遠近を抑えた平面的で装飾的な画面に、古典や神話の世界を静かで詩的に描きました。写実主義にも印象派にもアカデミズムにも属さない独自の作風は、象徴主義に数えられます。

代表作に《希望》《貧しき漁夫》、パンテオンやソルボンヌ大学の壁画があります。ピカソが作品を模写したとされるほか、黒田清輝ら日本の画家も訪ね、後の画家たちに大きな影響を与えました。', 'https://ja.wikipedia.org/wiki/%E3%83%94%E3%82%A8%E3%83%BC%E3%83%AB%E3%83%BB%E3%83%94%E3%83%A5%E3%83%B4%E3%82%A3%E3%82%B9%E3%83%BB%E3%83%89%E3%83%BB%E3%82%B7%E3%83%A3%E3%83%B4%E3%82%A1%E3%83%B3%E3%83%8C')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('フェルナン・クノップフ', 'Fernand Khnopff', 'クノップフ',
        1858, 1921, 'west', array['symbolism']::text[],
        '神秘的で静まりかえった画面を描いた、ベルギー象徴主義を代表する画家。', '1858年、ベルギーのグレムベルゲンに生まれました。大学で法律を学びましたが中退し、1876年にブリュッセル王立美術アカデミーに入学、1878年からはパリのアカデミー・ジュリアンでも学びました。ボードレールやフローベールらの文学、モローやドラクロワの絵画から刺激を受けています。

1883年には前衛的な芸術家の集まり「20人会」の創立メンバーとなりました。現実の人物や風景を描きながらも、閉ざされた室内や無表情な女性像を通して、記憶や夢、孤独といった目に見えないものを感じさせる神秘的な作風を築きました。舞台衣装や室内装飾も手がけています。

代表作に《シューマンを聞きながら》《記憶》《私は私自身に対してドアを閉ざす》《スフィンクスの愛撫》があります。1898年のウィーン分離派展に出品して高く評価され、クリムトにも影響を与えたとされます。', 'https://ja.wikipedia.org/wiki/%E3%83%95%E3%82%A7%E3%83%AB%E3%83%8A%E3%83%B3%E3%83%BB%E3%82%AF%E3%83%8E%E3%83%83%E3%83%97%E3%83%95')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ゾフィー・トイバー＝アルプ', 'Sophie Taeuber-Arp', 'トイバー＝アルプ',
        1889, 1943, 'west', array['dada']::text[],
        'チューリヒ・ダダで活躍し、幾何学的な抽象を切り開いたスイスの芸術家。', '1889年、スイスのダボスに生まれました。ザンクト・ガレンの職業学校で織物デザインを学び、ミュンヘンやハンブルクでも学んだのち、チューリヒではルドルフ・フォン・ラバンのもとで舞踊を学びました。

1915年に後に夫となるジャン・アルプと出会い、キャバレー・ヴォルテールを中心とするチューリヒのダダ運動に、ダンサーや人形使いとして加わりました。織物や刺繍、木彫りの《ダダの頭部》、絵画、ステンドグラスなど分野をこえて制作し、円や四角を組み合わせた幾何学的な抽象表現を早くから展開しました。

1943年、チューリヒで事故により亡くなりました。絵画と工芸の垣根を取り払った仕事は再評価が進み、1995年からはスイスの50フラン紙幣に肖像が使われています。', 'https://ja.wikipedia.org/wiki/%E3%82%BE%E3%83%95%E3%82%A3%E3%83%BC%E3%83%BB%E3%83%88%E3%82%A4%E3%83%90%E3%83%BC%EF%BC%9D%E3%82%A2%E3%83%AB%E3%83%97')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
